    uint32_t         item_size;   /* Kích thước một phần tử (byte) */
    uint32_t         max_items;   /* Dung lượng tối đa phần tử */
    uint32_t         head;        /* Chỉ số ghi phần tử tiếp theo */
    uint32_t         tail;        /* Chỉ số đọc phần tử tiếp theo */
