#include "rtos.h"

#if defined(UNIT_TEST) || !defined(__arm__)
#include <string.h>
#else
static void *rtos_memcpy(void *dst, const void *src, uint32_t n) {
    uint8_t *d = (uint8_t *)dst;
    const uint8_t *s = (const uint8_t *)src;
    while (n--) {
        *d++ = *s++;
    }
    return dst;
}
#define memcpy rtos_memcpy
#endif

static tcb_t *current_tcb = 0;
static tcb_t *ready_table[RTOS_MAX_PRIORITIES];
static uint32_t ready_map = 0;
static tcb_t *task_list = 0;
static uint32_t critical_nesting = 0;

void rtos_enter_critical(void) {
#if defined(__arm__) && !defined(UNIT_TEST)
    __asm volatile("cpsid i" : : : "memory");
#endif
    critical_nesting++;
}

void rtos_exit_critical(void) {
    if (critical_nesting > 0) {
        critical_nesting--;
        if (critical_nesting == 0) {
#if defined(__arm__) && !defined(UNIT_TEST)
            __asm volatile("cpsie i" : : : "memory");
#endif
        }
    }
}

void rtos_init(void) {
    current_tcb = 0;
    ready_map = 0;
    task_list = 0;
    critical_nesting = 0;
    for (uint32_t i = 0; i < RTOS_MAX_PRIORITIES; i++) {
        ready_table[i] = 0;
    }
}

tcb_t *rtos_get_current_task(void) {
    return current_tcb;
}

uint32_t rtos_get_ready_map(void) {
    return ready_map;
}

tcb_t *rtos_pick_next_task(void) {
    if (ready_map == 0) {
        return 0;
    }
    /* Sử dụng hàm nội tại đếm bit 0 từ MSB (tương đương lệnh CLZ trên ARM) */
    uint32_t lz = (uint32_t)__builtin_clz(ready_map);
    uint32_t highest_prio = 31 - lz;
    return ready_table[highest_prio];
}

bool rtos_task_create(tcb_t *tcb, const char *name, void (*entry)(void *), void *arg,
                      uint8_t priority, uint32_t *stack, uint32_t stack_size) {
    if (!tcb || !entry || !stack || stack_size < 32 || priority >= RTOS_MAX_PRIORITIES) {
        return false;
    }

    tcb->name = name;
    tcb->priority = priority;
    tcb->state = TASK_READY;
    tcb->delay_ticks = 0;
    tcb->stack_base = stack;
    tcb->stack_size = stack_size;
    tcb->waiting_on = 0;
    tcb->timed_out = false;

    /* Dựng ngăn xếp ban đầu cho tác vụ theo chuẩn ARM Cortex-M */
    uint32_t *sp = &stack[stack_size];

    /* Căn lề 8-byte cho ngăn xếp theo AAPCS */
    sp = (uint32_t *)((uintptr_t)sp & ~(uintptr_t)7);

    /* Khung phần cứng tự động pop khi thoát exception (8 words):
     * xPSR, PC, LR, R12, R3, R2, R1, R0
     */
    *(--sp) = (1UL << 24);         /* xPSR: Bật bit 24 (Thumb state) */
    *(--sp) = (uint32_t)(uintptr_t)entry; /* PC: Địa chỉ hàm tác vụ */
    *(--sp) = 0;                   /* LR: Return address */
    *(--sp) = 0;                   /* R12 */
    *(--sp) = 0;                   /* R3 */
    *(--sp) = 0;                   /* R2 */
    *(--sp) = 0;                   /* R1 */
    *(--sp) = (uint32_t)(uintptr_t)arg;   /* R0: Tham số truyền vào tác vụ */

    /* Khung phần mềm lưu thêm trong PendSV:
     * EXC_RETURN, R11 - R4 (9 words)
     * EXC_RETURN = 0xFFFFFFFD (Return to Thread mode, use PSP, standard frame không FPU)
     */
    *(--sp) = 0xFFFFFFFDU;         /* EXC_RETURN */
    *(--sp) = 0;                   /* R11 */
    *(--sp) = 0;                   /* R10 */
    *(--sp) = 0;                   /* R9 */
    *(--sp) = 0;                   /* R8 */
    *(--sp) = 0;                   /* R7 */
    *(--sp) = 0;                   /* R6 */
    *(--sp) = 0;                   /* R5 */
    *(--sp) = 0;                   /* R4 */

    tcb->sp = sp;

    rtos_enter_critical();

    /* Đưa vào bảng sẵn sàng */
    ready_table[priority] = tcb;
    ready_map |= (1UL << priority);

    /* Thêm vào danh sách toàn bộ tác vụ */
    tcb->next = task_list;
    task_list = tcb;

    /* Nếu chưa có tác vụ nào chạy thì gán tác vụ đầu tiên */
    if (current_tcb == 0) {
        current_tcb = tcb;
    }

    rtos_exit_critical();
    return true;
}

void rtos_yield(void) {
#if defined(__arm__) && !defined(UNIT_TEST)
    /* Kích hoạt ngắt PendSV trên ARM Cortex-M */
    volatile uint32_t *icsr = (volatile uint32_t *)0xE000ED04;
    *icsr = (1UL << 28); /* PENDSVSET */
#else
    /* Trên môi trường giả lập/test: cập nhật current_tcb sang tác vụ ưu tiên cao nhất */
    tcb_t *next = rtos_pick_next_task();
    if (next) {
        current_tcb = next;
    }
#endif
}

void rtos_delay_ms(uint32_t ms) {
    if (ms == 0) {
        rtos_yield();
        return;
    }

    rtos_enter_critical();
    if (current_tcb) {
        ready_map &= ~(1UL << current_tcb->priority);
        current_tcb->state = TASK_BLOCKED;
        current_tcb->delay_ticks = ms;
    }
    rtos_exit_critical();

    rtos_yield();
}

void rtos_tick(void) {
    rtos_enter_critical();

    tcb_t *curr = task_list;
    bool need_resched = false;

    while (curr) {
        if (curr->state == TASK_BLOCKED && curr->delay_ticks > 0) {
            curr->delay_ticks--;
            if (curr->delay_ticks == 0) {
                /* Đã hết thời hạn chờ */
                if (curr->waiting_on != 0) {
                    curr->timed_out = true;
                    curr->waiting_on = 0;
                }
                curr->state = TASK_READY;
                ready_table[curr->priority] = curr;
                ready_map |= (1UL << curr->priority);
                need_resched = true;
            }
        }
        curr = curr->next;
    }

    rtos_exit_critical();

    if (need_resched) {
        rtos_yield();
    }
}

void rtos_queue_init(rtos_queue_t *q, void *buffer, uint32_t item_size, uint32_t max_items) {
    if (!q || !buffer || item_size == 0 || max_items == 0) {
        return;
    }
    q->buffer = (uint8_t *)buffer;
    q->item_size = item_size;
    q->max_items = max_items;
    q->head = 0;
    q->tail = 0;
    q->count = 0;
    q->waiting_send = 0;
    q->waiting_recv = 0;
}

bool rtos_queue_send(rtos_queue_t *q, const void *item, uint32_t timeout_ticks) {
    if (!q || !item) {
        return false;
    }

    rtos_enter_critical();

    if (q->count < q->max_items) {
        /* Còn chỗ, sao chép dữ liệu vào vòng đệm */
        uint8_t *dst = q->buffer + (q->head * q->item_size);
        memcpy(dst, item, q->item_size);
        q->head = (q->head + 1) % q->max_items;
        q->count++;

        /* Đánh thức tác vụ đang chờ nhận nếu có */
        if (q->waiting_recv != 0) {
            tcb_t *w = q->waiting_recv;
            q->waiting_recv = 0;
            w->waiting_on = 0;
            w->timed_out = false;
            w->state = TASK_READY;
            ready_table[w->priority] = w;
            ready_map |= (1UL << w->priority);
        }

        rtos_exit_critical();
        rtos_yield();
        return true;
    }

    /* Hàng đợi đầy */
    if (timeout_ticks == 0 || current_tcb == 0) {
        rtos_exit_critical();
        return false;
    }

    /* Đưa tác vụ hiện tại vào trạng thái chờ gửi */
    q->waiting_send = current_tcb;
    current_tcb->waiting_on = q;
    current_tcb->timed_out = false;
    current_tcb->delay_ticks = timeout_ticks;
    current_tcb->state = TASK_BLOCKED;
    ready_map &= ~(1UL << current_tcb->priority);

    rtos_exit_critical();
    rtos_yield();

    return !current_tcb->timed_out;
}

bool rtos_queue_receive(rtos_queue_t *q, void *item, uint32_t timeout_ticks) {
    if (!q || !item) {
        return false;
    }

    rtos_enter_critical();

    if (q->count > 0) {
        /* Có dữ liệu, lấy ra từ vòng đệm */
        const uint8_t *src = q->buffer + (q->tail * q->item_size);
        memcpy(item, src, q->item_size);
        q->tail = (q->tail + 1) % q->max_items;
        q->count--;

        /* Đánh thức tác vụ chờ gửi nếu có */
        if (q->waiting_send != 0) {
            tcb_t *w = q->waiting_send;
            q->waiting_send = 0;
            w->waiting_on = 0;
            w->timed_out = false;
            w->state = TASK_READY;
            ready_table[w->priority] = w;
            ready_map |= (1UL << w->priority);
        }

        rtos_exit_critical();
        rtos_yield();
        return true;
    }

    /* Hàng đợi rỗng */
    if (timeout_ticks == 0 || current_tcb == 0) {
        rtos_exit_critical();
        return false;
    }

    /* Đưa tác vụ hiện tại vào trạng thái chờ nhận */
    q->waiting_recv = current_tcb;
    current_tcb->waiting_on = q;
    current_tcb->timed_out = false;
    current_tcb->delay_ticks = timeout_ticks;
    current_tcb->state = TASK_BLOCKED;
    ready_map &= ~(1UL << current_tcb->priority);

    rtos_exit_critical();
    rtos_yield();

    if (current_tcb->timed_out) {
        return false;
    }

    /* Nếu được đánh thức và có dữ liệu thì lấy */
    rtos_enter_critical();
    if (q->count > 0) {
        const uint8_t *src = q->buffer + (q->tail * q->item_size);
        memcpy(item, src, q->item_size);
        q->tail = (q->tail + 1) % q->max_items;
        q->count--;
        rtos_exit_critical();
        return true;
    }
    rtos_exit_critical();
    return false;
}

