static tcb_t *current_tcb = 0;
static tcb_t *ready_table[RTOS_MAX_PRIORITIES];
static uint32_t ready_map = 0;
static tcb_t *task_list = 0;
static uint32_t critical_nesting = 0;

void rtos_enter_critical(void) {
    critical_nesting++;
}

void rtos_exit_critical(void) {
    if (critical_nesting > 0) {
        critical_nesting--;
    }
}

void rtos_init(void) {
    current_tcb = 0;
    ready_map = 0;
    task_list = 0;
    critical_nesting = 0;
    for (uint32_t i = 0; i < RTOS_MAX_PRIORITIES; i++) {
        ready_table[i] = 0;
    }
}

tcb_t *rtos_get_current_task(void) {
    return current_tcb;
}

uint32_t rtos_get_ready_map(void) {
    return ready_map;
}

tcb_t *rtos_pick_next_task(void) {
    if (ready_map == 0) {
        return 0;
    }
    /* Đếm số bit 0 từ MSB để tìm mức ưu tiên cao nhất trong ready_map */
    uint32_t lz = (uint32_t)__builtin_clz(ready_map);
    uint32_t highest_prio = (RTOS_MAX_PRIORITIES - 1) - lz;
    return ready_table[highest_prio];
}

void rtos_yield(void) {
    tcb_t *next = rtos_pick_next_task();
    if (next != 0) {
        current_tcb = next;
    }
}

bool rtos_task_create(tcb_t *tcb, const char *name, void (*entry)(void *), void *arg,
                      uint8_t priority, uint32_t *stack, uint32_t stack_size) {
    if (!tcb || !entry || !stack || stack_size < RTOS_MAX_PRIORITIES || priority >= RTOS_MAX_PRIORITIES) {
        return false;
    }

    tcb->name = name;
    tcb->priority = priority;
    tcb->state = TASK_READY;
    tcb->delay_ticks = 0;
    tcb->stack_base = stack;
    tcb->stack_size = stack_size;
    tcb->waiting_on = 0;
    tcb->timed_out = false;

    /* Khởi tạo con trỏ ngăn xếp đỉnh */
    uint32_t *sp = &stack[stack_size];
    sp = (uint32_t *)((uintptr_t)sp & ~(uintptr_t)7);
    tcb->sp = sp;

    rtos_enter_critical();

    ready_table[priority] = tcb;
    ready_map |= (1UL << priority);

    tcb->next = task_list;
    task_list = tcb;

    if (current_tcb == 0) {
        current_tcb = tcb;
    } else {
        /* Tiền định: nếu tác vụ mới có mức ưu tiên cao hơn tác vụ hiện tại */
        if (priority > current_tcb->priority) {
            current_tcb = tcb;
        }
    }

    rtos_exit_critical();
    return true;
}

void rtos_delay_ms(uint32_t ms) {
    if (ms == 0) {
        rtos_yield();
        return;
    }

    rtos_enter_critical();
    if (current_tcb != 0) {
        ready_map &= ~(1UL << current_tcb->priority);
        current_tcb->state = TASK_BLOCKED;
        current_tcb->delay_ticks = ms;
    }
    rtos_exit_critical();

    rtos_yield();
}

void rtos_tick(void) {
    rtos_enter_critical();

    tcb_t *curr = task_list;
    bool need_resched = false;

    while (curr) {
        if (curr->state == TASK_BLOCKED && curr->delay_ticks > 0) {
            curr->delay_ticks--;
            if (curr->delay_ticks == 0) {
                if (curr->waiting_on != 0) {
                    curr->timed_out = true;
                    curr->waiting_on = 0;
                }
                curr->state = TASK_READY;
                ready_table[curr->priority] = curr;
                ready_map |= (1UL << curr->priority);
                need_resched = true;
            }
        }
        curr = curr->next;
    }

    rtos_exit_critical();

    if (need_resched) {
        rtos_yield();
    }
}

void rtos_queue_init(rtos_queue_t *q, void *buffer, uint32_t item_size, uint32_t max_items) {
    if (!q || !buffer || item_size == 0 || max_items == 0) {
        return;
    }
    q->buffer = (uint8_t *)buffer;
    q->item_size = item_size;
    q->max_items = max_items;
    q->head = 0;
    q->tail = 0;
    q->count = 0;
    q->waiting_send = 0;
    q->waiting_recv = 0;
}

bool rtos_queue_send(rtos_queue_t *q, const void *item, uint32_t timeout_ticks) {
    if (!q || !item) {
        return false;
    }

    rtos_enter_critical();

    if (q->count < q->max_items) {
        uint8_t *dst = q->buffer + (q->head * q->item_size);
        memcpy(dst, item, q->item_size);
        q->head = (q->head + 1) % q->max_items;
        q->count++;

        if (q->waiting_recv != 0) {
            tcb_t *w = q->waiting_recv;
            q->waiting_recv = 0;
            w->waiting_on = 0;
            w->timed_out = false;
            w->state = TASK_READY;
            ready_table[w->priority] = w;
            ready_map |= (1UL << w->priority);
        }

        rtos_exit_critical();
        rtos_yield();
        return true;
    }

    if (timeout_ticks == 0 || current_tcb == 0) {
        rtos_exit_critical();
        return false;
    }

    q->waiting_send = current_tcb;
    current_tcb->waiting_on = q;
    current_tcb->timed_out = false;
    current_tcb->delay_ticks = timeout_ticks;
    current_tcb->state = TASK_BLOCKED;
    ready_map &= ~(1UL << current_tcb->priority);

    rtos_exit_critical();
    rtos_yield();

    return !current_tcb->timed_out;
}

bool rtos_queue_receive(rtos_queue_t *q, void *item, uint32_t timeout_ticks) {
    if (!q || !item) {
        return false;
    }

    rtos_enter_critical();

    if (q->count > 0) {
        const uint8_t *src = q->buffer + (q->tail * q->item_size);
        memcpy(item, src, q->item_size);
        q->tail = (q->tail + 1) % q->max_items;
        q->count--;

        if (q->waiting_send != 0) {
            tcb_t *w = q->waiting_send;
            q->waiting_send = 0;
            w->waiting_on = 0;
            w->timed_out = false;
            w->state = TASK_READY;
            ready_table[w->priority] = w;
            ready_map |= (1UL << w->priority);
        }

        rtos_exit_critical();
        rtos_yield();
        return true;
    }

    if (timeout_ticks == 0 || current_tcb == 0) {
        rtos_exit_critical();
        return false;
    }

    q->waiting_recv = current_tcb;
    current_tcb->waiting_on = q;
    current_tcb->timed_out = false;
    current_tcb->delay_ticks = timeout_ticks;
    current_tcb->state = TASK_BLOCKED;
    ready_map &= ~(1UL << current_tcb->priority);

    rtos_exit_critical();
    rtos_yield();

    if (current_tcb->timed_out) {
        return false;
    }

    rtos_enter_critical();
    if (q->count > 0) {
        const uint8_t *src = q->buffer + (q->tail * q->item_size);
        memcpy(item, src, q->item_size);
        q->tail = (q->tail + 1) % q->max_items;
        q->count--;
        rtos_exit_critical();
        return true;
    }
    rtos_exit_critical();
    return false;
}

#include <stdio.h>
#include <stdbool.h>
#include <string.h>
#include "../firmware/rtos.h"

#define ID_TASK_A 101
#define ID_TASK_B 102

static uint32_t trace[16];
static uint32_t trace_idx = 0;

static void record_trace(uint32_t id) {
    if (trace_idx < 16) {
        trace[trace_idx++] = id;
    }
}

int main(void) {
    rtos_init();

    /* ========================================================
     * Ca 1: Chuyển ngữ cảnh giữa Task A và Task B khi Task A trễ
     * ======================================================== */
    uint32_t stack_a[64];
    uint32_t stack_b[64];
    tcb_t tcb_a;
    tcb_t tcb_b;

    trace_idx = 0;

    /* Task A có ưu tiên cao hơn Task B */
    uint8_t prio_a = 15;
    uint8_t prio_b = 8;
    uint32_t delay_ticks = 5;

    rtos_task_create(&tcb_a, "TaskA", (void (*)(void *))0, 0, prio_a, stack_a, 64);
    rtos_task_create(&tcb_b, "TaskB", (void (*)(void *))0, 0, prio_b, stack_b, 64);

    /* 1. Ban đầu bộ lập lịch phải chọn Task A */
    tcb_t *curr = rtos_pick_next_task();
    bool ca1_step1 = (curr == &tcb_a);
    if (curr) record_trace(ID_TASK_A);

    /* 2. Task A gọi trễ 5 nhịp -> Task A bị BLOCKED */
    rtos_delay_ms(delay_ticks);

    /* Bộ lập lịch BẮT BUỘC phải chuyển sang Task B */
    curr = rtos_pick_next_task();
    bool ca1_step2 = (curr == &tcb_b);
    if (curr) record_trace(ID_TASK_B);

    /* 3. Cho nhịp tick chạy 5 lần để hết trễ */
    for (uint32_t i = 0; i < delay_ticks; i++) {
        rtos_tick();
    }

    /* 4. Task A hết trễ, sẵn sàng trở lại -> bộ lập lịch tiền định chọn lại Task A */
    curr = rtos_pick_next_task();
    bool ca1_step3 = (curr == &tcb_a);
    if (curr) record_trace(ID_TASK_A);

    /* Mốc so sánh ĐỘC LẬP: Golden trace [ID_TASK_A, ID_TASK_B, ID_TASK_A] */
    bool ca1_ok = ca1_step1 && ca1_step2 && ca1_step3 && (trace_idx == 3) &&
                  (trace[0] == ID_TASK_A) && (trace[1] == ID_TASK_B) && (trace[2] == ID_TASK_A);

    /* ========================================================
     * Ca 2: Hàng đợi tĩnh - Task B gửi tin đánh thức Task A
     * ======================================================== */
    rtos_init();
    rtos_task_create(&tcb_a, "TaskA", (void (*)(void *))0, 0, prio_a, stack_a, 64);
    rtos_task_create(&tcb_b, "TaskB", (void (*)(void *))0, 0, prio_b, stack_b, 64);

    rtos_queue_t queue;
    uint32_t q_buffer[4];
    rtos_queue_init(&queue, q_buffer, sizeof(uint32_t), 4);

    /* Task A đọc từ hàng đợi rỗng với timeout -> Task A bị BLOCKED */
    uint32_t received_val = 0;
    bool recv_ret = rtos_queue_receive(&queue, &received_val, 10);
    bool ca2_step1 = (!recv_ret && tcb_a.state == TASK_BLOCKED);

    /* Bộ lập lịch chuyển sang Task B */
    curr = rtos_pick_next_task();
    bool ca2_step2 = (curr == &tcb_b);

    /* Task B gửi dữ liệu vào hàng đợi */
    uint32_t send_val = 12345;
    bool send_ret = rtos_queue_send(&queue, &send_val, 0);

    /* Task A phải được đánh thức về READY ngay lập tức và được chọn chạy lại */
    curr = rtos_pick_next_task();
    bool ca2_step3 = (send_ret && curr == &tcb_a && tcb_a.state == TASK_READY);

    bool ca2_ok = ca2_step1 && ca2_step2 && ca2_step3;

    /* ========================================================
     * Ca 3: Hàng đợi hết thời hạn (Timeout) trả về false
     * ======================================================== */
    rtos_init();
    rtos_task_create(&tcb_a, "TaskA", (void (*)(void *))0, 0, prio_a, stack_a, 64);
    rtos_queue_init(&queue, q_buffer, sizeof(uint32_t), 4);

    /* Task A chờ nhận tin với timeout 3 nhịp */
    rtos_queue_receive(&queue, &received_val, 3);
    bool ca3_step1 = (tcb_a.state == TASK_BLOCKED);

    /* Cho 3 nhịp tick trôi qua mà không ai gửi tin */
    rtos_tick();
    rtos_tick();
    rtos_tick();

    /* Task A phải hết timeout, quay lại READY và có timed_out = true */
    bool ca3_ok = ca3_step1 && (tcb_a.state == TASK_READY) && (tcb_a.timed_out == true);

    /* ========================================================
     * Ca 4: Tiền định theo 32 mức ưu tiên dùng CLZ
     * ======================================================== */
    rtos_init();
    tcb_t tcb_low, tcb_mid, tcb_high;
    uint32_t s_low[64], s_mid[64], s_high[64];

    rtos_task_create(&tcb_low, "Low", (void (*)(void *))0, 0, 1, s_low, 64);
    rtos_task_create(&tcb_mid, "Mid", (void (*)(void *))0, 0, 14, s_mid, 64);
    rtos_task_create(&tcb_high, "High", (void (*)(void *))0, 0, 31, s_high, 64);

    /* Bộ lập lịch phải chọn High (31) */
    curr = rtos_pick_next_task();
    bool ca4_step1 = (curr == &tcb_high);

    /* Chặn High -> phải chuyển sang Mid (14) */
    rtos_delay_ms(10);
    curr = rtos_pick_next_task();
    bool ca4_step2 = (curr == &tcb_mid);

    /* Chặn Mid -> phải chuyển sang Low (1) */
    rtos_delay_ms(10);
    curr = rtos_pick_next_task();
    bool ca4_step3 = (curr == &tcb_low);

    bool ca4_ok = ca4_step1 && ca4_step2 && ca4_step3;

    /* In ĐÚNG MỘT dòng JSON ở dòng cuối cùng theo quy ước của test.run */
    printf("{\"ca\": ["
           "{\"ten\": \"Chuyen ngu canh Task A -> Task B -> Task A khi delay\", \"dat\": %s, \"vi\": \"Vong lap dieu phoi ghi nhan dung chuoi vet thuc thi [A, B, A]\"},"
           "{\"ten\": \"Danh thuc tac vu tien dinh qua hang doi tinh\", \"dat\": %s, \"vi\": \"Task B gui tin danh thuc Task A dang blocked ve ready lap tuc\"},"
           "{\"ten\": \"Hang doi het thoi han (Timeout)\", \"dat\": %s, \"vi\": \"Task A het timeout sau 3 tick va danh dau timed_out chinh xac\"},"
           "{\"ten\": \"Tien dinh 32 muc uu tien bang CLZ\", \"dat\": %s, \"vi\": \"Bo lap lich luon chon dung tac vu co muc uu tien cao nhat\"}"
           "]}\n",
           ca1_ok ? "true" : "false",
           ca2_ok ? "true" : "false",
           ca3_ok ? "true" : "false",
           ca4_ok ? "true" : "false");

    return (ca1_ok && ca2_ok && ca3_ok && ca4_ok) ? 0 : 1;
}

