           ca1_ok ? "true" : "false",
           ca2_ok ? "true" : "false",
           ca3_ok ? "true" : "false",
           ca4_ok ? "true" : "false");

    return (ca1_ok && ca2_ok && ca3_ok && ca4_ok) ? 0 : 1;
}

