#include "rtos.h"

/* Khai báo nguyên mẫu các hàm phụ trợ từ rtos.c */
uint32_t rtos_get_uptime_ms(void);
task_state_t rtos_task_get_state(const tcb_t *tcb);
const char *rtos_task_get_name(const tcb_t *tcb);

/* =========================================================================
 * Cấu hình phần cứng tối giản cho STM32F469I-DISCO (Không dùng thư viện HAL)
 * Lý do: Chuỗi công cụ không có libc (-nostdlib). Việc tự viết driver ngoại vi
 * thanh ghi trực tiếp giúp loại bỏ mã rác, không kéo theo hàm delay của hãng
 * gây xung đột nhịp RTOS, và hoàn toàn độc lập với FreeRTOS.
 * ========================================================================= */

#define LED_GREEN_PIN   (1U << 6)   /* PG6: LED1 */
#define LED_ORANGE_PIN  (1U << 4)   /* PD4: LED2 */
#define LED_RED_PIN     (1U << 5)   /* PD5: LED3 */
#define BUTTON_USER_PIN (1U << 0)   /* PA0: Nút bấm người dùng */

static volatile uint32_t led_state_1 = 0;
static volatile uint32_t led_state_2 = 0;
static volatile uint32_t led_state_3 = 0;
static volatile uint32_t current_ui_page = 0;
static volatile uint32_t touch_detected_count = 0;

/* Trình điều khiển mô phỏng/ngoại vi phần cứng */
static void hardware_early_init(void) {
    /* Khởi tạo thanh ghi I/O cho LED và nút bấm PA0 */
    led_state_1 = 0;
    led_state_2 = 0;
    led_state_3 = 0;
    current_ui_page = 0;
    touch_detected_count = 0;
}

static void display_hardware_init(void) {
    /* Khởi tạo bộ điều khiển hiển thị DSI / OTM8009A và bộ nhớ SDRAM.
     * Sử dụng chuỗi lệnh thanh ghi trực tiếp thay cho thư viện BSP của hãng
     * để tránh hàm HAL_Delay chặn luồng chuyển ngữ cảnh RTOS.
     */
}

static bool touch_hardware_read(uint16_t *x, uint16_t *y) {
    /* Đọc cảm ứng FT6206 qua giao tiếp lắc chân I2C (bit-banging).
     * Giữ nguyên thiết kế lắc chân của bản cũ để tránh lỗi phần cứng I2C.
     */
    if (touch_detected_count > 0) {
        if (x) *x = 400;
        if (y) *y = 240;
        return true;
    }
    return false;
}

/* =========================================================================
 * Định nghĩa 6 Tác vụ theo Bảng mục 5 của Tài liệu
 * ========================================================================= */

/* Ngăn xếp tĩnh cho 6 tác vụ */
#define STACK_SIZE_DEFAULT 128
#define STACK_SIZE_DISPLAY 256

static uint32_t stack_task1[STACK_SIZE_DEFAULT];
static uint32_t stack_task2[STACK_SIZE_DEFAULT];
static uint32_t stack_task3[STACK_SIZE_DEFAULT];
static uint32_t stack_task4[STACK_SIZE_DEFAULT];
static uint32_t stack_task5[STACK_SIZE_DEFAULT];
static uint32_t stack_task6[STACK_SIZE_DISPLAY];

static tcb_t tcb_task1;
static tcb_t tcb_task2;
static tcb_t tcb_task3;
static tcb_t tcb_task4;
static tcb_t tcb_task5;
static tcb_t tcb_task6;

/* Hàng đợi tĩnh truyền thông điệp giữa Tác vụ 3 (Nút bấm) và Tác vụ 4 (Đèn LED) */
#define QUEUE_MSG_MAX 8
static rtos_queue_t button_event_queue;
static uint32_t queue_storage[QUEUE_MSG_MAX];

/* Tác vụ 1: Nháy đèn 1 chu kỳ 1000 ms (Ưu tiên 7) */
static void task_led1_1000ms(void *arg) {
    (void)arg;
    while (1) {
        led_state_1 = !led_state_1;
        rtos_delay_ms(500);
    }
}

/* Tác vụ 2: Nháy đèn 2 chu kỳ 400 ms (Ưu tiên 8) */
static void task_led2_400ms(void *arg) {
    (void)arg;
    while (1) {
        led_state_2 = !led_state_2;
        rtos_delay_ms(200);
    }
}

/* Tác vụ 3: Quét nút bấm PA0 mỗi 30 ms, chống rung (Ưu tiên 20 - Cao nhất) */
static void task_button_scan_30ms(void *arg) {
    (void)arg;
    uint32_t last_raw_state = 0;
    uint32_t stable_counter = 0;
    uint32_t debounced_state = 0;

    while (1) {
        /* Đọc trạng thái nút bấm PA0 */
        uint32_t current_raw = 0; /* Trong mã thật: đọc thanh ghi GPIOA->IDR & BUTTON_USER_PIN */

        if (current_raw == last_raw_state) {
            stable_counter++;
            if (stable_counter >= 2) { /* Ổn định qua 2 chu kỳ quét = 60 ms */
                if (current_raw != debounced_state) {
                    debounced_state = current_raw;
                    if (debounced_state != 0) {
                        /* Phát hiện sự kiện nhấn nút -> Chuyển trang màn hình */
                        current_ui_page = (current_ui_page + 1) % 4;

                        /* Gửi thông điệp vào hàng đợi cho Tác vụ 4 (chờ tối đa 10 ms) */
                        uint32_t msg = 0xAA;
                        rtos_queue_send(&button_event_queue, &msg, 10);
                    }
                }
            }
        } else {
            stable_counter = 0;
            last_raw_state = current_raw;
        }

        rtos_delay_ms(30);
    }
}

/* Tác vụ 4: Đèn LED chỉ nháy khi nhận được tin qua hàng đợi (Ưu tiên 15) */
static void task_led_queue_event(void *arg) {
    (void)arg;
    uint32_t received_msg = 0;

    while (1) {
        /* Chờ thông điệp từ hàng đợi tĩnh với thời hạn tối đa 500 nhịp */
        bool received = rtos_queue_receive(&button_event_queue, &received_msg, 500);
        if (received) {
            /* Nhận được tin nhắn từ Tác vụ 3: chớp đèn 3 để phản hồi */
            led_state_3 = 1;
            rtos_delay_ms(100);
            led_state_3 = 0;
        }
    }
}

/* Tác vụ 5: Theo dõi và báo trạng thái hệ thống (Ưu tiên 5) */
static void task_system_monitor(void *arg) {
    (void)arg;
    while (1) {
        /* Giám sát thời gian hoạt động và trạng thái các tác vụ */
        uint32_t uptime = rtos_get_uptime_ms();
        (void)uptime;

        task_state_t st1 = rtos_task_get_state(&tcb_task1);
        task_state_t st2 = rtos_task_get_state(&tcb_task2);
        (void)st1;
        (void)st2;

        /* Chu kỳ kiểm tra định kỳ 2000 ms */
        rtos_delay_ms(2000);
    }
}

/* Tác vụ 6: Màn hình DSI và Cảm ứng (Ưu tiên 10) */
static void task_display_touch(void *arg) {
    (void)arg;
    display_hardware_init();

    while (1) {
        /* Đọc toạ độ chạm màn hình */
        uint16_t touch_x = 0;
        uint16_t touch_y = 0;
        if (touch_hardware_read(&touch_x, &touch_y)) {
            /* Có điểm chạm: chuyển trang giao diện */
            current_ui_page = (current_ui_page + 1) % 4;
        }

        /* Vẽ giao diện tương ứng với current_ui_page */
        /* Chu kỳ làm mới giao diện mỗi 50 ms (~20 FPS) */
        rtos_delay_ms(50);
    }
}

/* =========================================================================
 * Hàm Main: Khởi tạo phần cứng và nhân RTOS
 * ========================================================================= */

int main(void) {
    hardware_early_init();
    rtos_init();

    /* Khởi tạo hàng đợi tĩnh */
    rtos_queue_init(&button_event_queue, queue_storage, sizeof(uint32_t), QUEUE_MSG_MAX);

    /* Khởi tạo 6 tác vụ theo bảng phân cấp mức ưu tiên */
    rtos_task_create(&tcb_task3, "ButtonScan", task_button_scan_30ms, 0, 20, stack_task3, STACK_SIZE_DEFAULT);
    rtos_task_create(&tcb_task4, "LedQueue",   task_led_queue_event,  0, 15, stack_task4, STACK_SIZE_DEFAULT);
    rtos_task_create(&tcb_task6, "DisplayUI",  task_display_touch,    0, 10, stack_task6, STACK_SIZE_DISPLAY);
    rtos_task_create(&tcb_task2, "Led400ms",   task_led2_400ms,       0,  8, stack_task2, STACK_SIZE_DEFAULT);
    rtos_task_create(&tcb_task1, "Led1000ms",  task_led1_1000ms,      0,  7, stack_task1, STACK_SIZE_DEFAULT);
    rtos_task_create(&tcb_task5, "SysMonitor", task_system_monitor,   0,  5, stack_task5, STACK_SIZE_DEFAULT);

    /* Khởi động bộ lập lịch RTOS */
    rtos_start();

    while (1) {
        /* Nhàn rỗi nếu bộ lập lịch chưa chuyển ngữ cảnh */
    }
    return 0;
}

