#include "rtos.h"
#if defined(__arm__)
#include "stm32f4xx.h"
extern void HAL_IncTick(void);
#endif

/* Ngắt SysTick phục vụ nhịp RTOS và nhịp HAL */
void SysTick_Handler(void) {
#if defined(__arm__)
    HAL_IncTick();
#endif
    rtos_tick();
}

/* Khởi động bộ lập lịch RTOS */
void rtos_start(void) {
    tcb_t *first = rtos_pick_next_task();
    if (!first) {
        while (1) {}
    }

#if defined(__arm__)
    /* Cấu hình ưu tiên ngắt:
     * - PendSV: Mức 15 (thấp nhất tuyệt đối) để context switch không ngắt quãng các ISR khác.
     * - SysTick: Mức 14 (hoặc 15). Đặt mức 14 để SysTick cao hơn PendSV, đảm bảo khi SysTick
     *   kích hoạt PendSV thì PendSV chỉ nổ sau khi SysTick ISR hoàn thành, không bị gián đoạn giữa chừng.
     */
    NVIC_SetPriority(PendSV_IRQn, 0x0F);
    NVIC_SetPriority(SysTick_IRQn, 0x0E);

    /* Cấu hình SysTick ở xung nhịp 180 MHz cho nhịp 1 000 Hz (1 ms):
     * Reload = 180 000 000 / 1 000 - 1 = 179 999
     */
    SysTick->LOAD = (180000000UL / 1000UL) - 1UL;
    SysTick->VAL = 0UL;
    SysTick->CTRL = SysTick_CTRL_CLKSOURCE_Msk |
                    SysTick_CTRL_TICKINT_Msk   |
                    SysTick_CTRL_ENABLE_Msk;
#endif

    /* Chuyển quyền điều khiển cho tác vụ ưu tiên cao nhất */
    rtos_yield();
}

#include <stdio.h>
#include <stdbool.h>
#include <stdint.h>
#define RTOS_WEAK __attribute__((weak))
#include "../firmware/control_rtos.c"

static tcb_t *trace[16];
static uint32_t trace_idx = 0;

static void dummy_task(void *arg) {
    (void)arg;
}

static void record_trace(tcb_t *task) {
    if (trace_idx < 16) {
        trace[trace_idx++] = task;
    }
}

int main(void) {
    rtos_init();

    /* ========================================================
     * Ca 1: Chuyển ngữ cảnh giữa Task A và Task B khi Task A trễ
     * ======================================================== */
    uint32_t stack_a[64];
    uint32_t stack_b[64];
    tcb_t tcb_a;
    tcb_t tcb_b;

    trace_idx = 0;

    /* Task A có ưu tiên cao hơn Task B */
    uint8_t prio_a = 15;
    uint8_t prio_b = 8;
    uint32_t delay_ticks = 5;

    bool c1 = rtos_task_create(&tcb_a, "TaskA", dummy_task, 0, prio_a, stack_a, 64);
    bool c2 = rtos_task_create(&tcb_b, "TaskB", dummy_task, 0, prio_b, stack_b, 64);

    /* 1. Ban đầu bộ lập lịch phải chọn Task A */
    tcb_t *curr = rtos_pick_next_task();
    bool ca1_step1 = (c1 && c2 && curr == &tcb_a);
    if (curr) record_trace(curr);

    /* 2. Task A gọi trễ 5 nhịp -> Task A bị BLOCKED */
    rtos_delay_ms(delay_ticks);

    /* Bộ lập lịch BẮT BUỘC phải chuyển sang Task B */
    curr = rtos_pick_next_task();
    bool ca1_step2 = (curr == &tcb_b);
    if (curr) record_trace(curr);

    /* 3. Cho nhịp tick chạy 5 lần để hết trễ */
    for (uint32_t i = 0; i < delay_ticks; i++) {
        rtos_tick();
    }

    /* 4. Task A hết trễ, sẵn sàng trở lại -> bộ lập lịch tiền định chọn lại Task A */
    curr = rtos_pick_next_task();
    bool ca1_step3 = (curr == &tcb_a);
    if (curr) record_trace(curr);

    /* Mốc so sánh ĐỘC LẬP: vết thực thi đúng thứ tự [&tcb_a, &tcb_b, &tcb_a] */
    bool ca1_ok = ca1_step1 && ca1_step2 && ca1_step3 && (trace_idx == 3) &&
                  (trace[0] == &tcb_a) && (trace[1] == &tcb_b) && (trace[2] == &tcb_a);

    /* ========================================================
     * Ca 2: Hàng đợi tĩnh - Task B gửi tin đánh thức Task A
     * ======================================================== */
    rtos_init();
    rtos_task_create(&tcb_a, "TaskA", dummy_task, 0, prio_a, stack_a, 64);
    rtos_task_create(&tcb_b, "TaskB", dummy_task, 0, prio_b, stack_b, 64);

    rtos_queue_t queue;
    uint32_t q_buffer[4];
    rtos_queue_init(&queue, q_buffer, sizeof(uint32_t), 4);

    /* Task A đọc từ hàng đợi rỗng với timeout -> Task A bị BLOCKED */
    uint32_t received_val = 0;
    bool recv_ret = rtos_queue_receive(&queue, &received_val, 10);
    bool ca2_step1 = (!recv_ret && tcb_a.state == TASK_BLOCKED);

    /* Bộ lập lịch chuyển sang Task B */
    curr = rtos_pick_next_task();
    bool ca2_step2 = (curr == &tcb_b);

    /* Task B gửi tin vào hàng đợi -> đánh thức Task A ngay lập tức */
    uint32_t send_val = 0xAA55AA55;
    bool send_ret = rtos_queue_send(&queue, &send_val, 0);
    bool ca2_step3 = send_ret && (tcb_a.state == TASK_READY);

    /* Bộ lập lịch tiền định lập tức chọn lại Task A có ưu tiên cao hơn */
    curr = rtos_pick_next_task();
    bool ca2_step4 = (curr == &tcb_a);

    bool ca2_ok = ca2_step1 && ca2_step2 && ca2_step3 && ca2_step4;

    /* ========================================================
     * Ca 3: Hàng đợi hết thời hạn (Timeout)
     * ======================================================== */
    rtos_init();
    rtos_task_create(&tcb_a, "TaskA", dummy_task, 0, prio_a, stack_a, 64);

    rtos_queue_init(&queue, q_buffer, sizeof(uint32_t), 4);
    recv_ret = rtos_queue_receive(&queue, &received_val, 3);
    bool ca3_step1 = (!recv_ret && tcb_a.state == TASK_BLOCKED && tcb_a.delay_ticks == 3);

    /* Cho trôi qua 3 nhịp tick */
    rtos_tick();
    bool ca3_step2 = (tcb_a.state == TASK_BLOCKED && tcb_a.delay_ticks == 2);
    rtos_tick();
    bool ca3_step3 = (tcb_a.state == TASK_BLOCKED && tcb_a.delay_ticks == 1);
    rtos_tick();

    /* Đã hết 3 tick -> Task A phải được đánh thức về READY kèm cờ timed_out = true */
    bool ca3_step4 = (tcb_a.state == TASK_READY && tcb_a.timed_out == true && tcb_a.waiting_on == 0);

    bool ca3_ok = ca3_step1 && ca3_step2 && ca3_step3 && ca3_step4;

    /* ========================================================
     * Ca 4: Tiền định 32 mức ưu tiên bằng đếm bit (CLZ)
     * ======================================================== */
    rtos_init();
    tcb_t tcb_low, tcb_mid, tcb_high;
    uint32_t s_low[64], s_mid[64], s_high[64];

    rtos_task_create(&tcb_low,  "Low",  dummy_task, 0,  1, s_low,  64);
    rtos_task_create(&tcb_mid,  "Mid",  dummy_task, 0, 14, s_mid,  64);
    rtos_task_create(&tcb_high, "High", dummy_task, 0, 31, s_high, 64);

    /* Chọn High (31) */
    curr = rtos_pick_next_task();
    bool ca4_step1 = (curr == &tcb_high);

    /* Chặn High -> phải chuyển sang Mid (14) */
    rtos_delay_ms(10);
    curr = rtos_pick_next_task();
    bool ca4_step2 = (curr == &tcb_mid);

    /* Chặn Mid -> phải chuyển sang Low (1) */
    rtos_delay_ms(10);
    curr = rtos_pick_next_task();
    bool ca4_step3 = (curr == &tcb_low);

    bool ca4_ok = ca4_step1 && ca4_step2 && ca4_step3;

    /* ========================================================
     * Ca 5: Sơn ngăn xếp 0xA5A5A5A5 và đo mức nước (Watermark)
     * ======================================================== */
    rtos_init();
